"use server";
import { revalidatePath } from "next/cache";
import { signIn } from "@/auth";
import { requireAdmin } from "./auth";
import { startAdminChallenge } from "./reauth";
import { changeOverride, changeSuspension, changeControl } from "./mutations";
import type { MutationResult } from "./contracts";
async function refresh(result: MutationResult) {
  if (result.ok) revalidatePath("/admin", "layout");
  return result;
}
export async function setPlanOverride(input: unknown) {
  return refresh(await changeOverride(input));
}
export async function setSuspended(input: unknown) {
  return refresh(await changeSuspension(input));
}
export async function setSystemControl(input: unknown) {
  return refresh(await changeControl(input));
}
export async function reauthenticateAdmin() {
  const actor = await requireAdmin();
  await startAdminChallenge(actor.id);
  await signIn("google-admin", { redirectTo: "/admin" });
}
